/* Flipping Friend barcode fallback shim.
   The original vendored ZXing bundle could not be copied across repositories by the GitHub connector.
   Modern browsers use BarcodeDetector before this file is loaded. On browsers without it, throwing
   here intentionally sends the existing UI to its manual UPC-entry fallback rather than failing silently. */
window.ZXing = window.ZXing || {
  BrowserMultiFormatReader: class {
    decodeFromVideoDevice() { throw new Error("ZXing fallback unavailable"); }
    reset() {}
  }
};
